div.script:
(function () {
    /* ── Particules hero ── */
    function initParticles() {
        var wrap = document.getElementById('pm-particles');
        if (!wrap) return;
        for (var i = 0; i < 28; i++) {
            var p = document.createElement('div');
            p.className = 'pm-particle';
            var size = Math.random() * 4 + 1;
            p.style.cssText = [
                'width:' + size + 'px',
                'height:' + size + 'px',
                'left:' + Math.random() * 100 + '%',
                'animation-duration:' + (Math.random() * 12 + 8) + 's',
                'animation-delay:' + (Math.random() * 10) + 's'
            ].join(';');
            wrap.appendChild(p);
        }
    }

    /* ── Carrousel hero ── */
    function initHero() {
        var slides = document.querySelectorAll('.pm-hero-slide');
        var indicators = document.querySelectorAll('.pm-indicator');
        if (!slides.length) return;
        var current = 0;
        function goTo(n) {
            slides[current].classList.remove('active');
            indicators[current] && indicators[current].classList.remove('active');
            current = (n + slides.length) % slides.length;
            slides[current].classList.add('active');
            indicators[current] && indicators[current].classList.add('active');
        }
        indicators.forEach(function(ind) {
            ind.addEventListener('click', function() {
                goTo(+this.dataset.slide);
            });
        });
        setInterval(function() { goTo(current + 1); }, 5000);
    }

    /* ── Typewriter hero ── */
    function initTypewriter() {
        var el = document.getElementById('pm-typed-text');
        if (!el) return;
        var lang = (document.documentElement.lang || 'fr').toLowerCase();
        var words = lang.startsWith('en')
            ? (el.dataset.wordsEn || '').split(',')
            : (el.dataset.wordsFr || '').split(',');
        var wi = 0, ci = 0, deleting = false;
        function tick() {
            var word = words[wi];
            if (!deleting) {
                el.textContent = word.slice(0, ++ci);
                if (ci === word.length) { deleting = true; setTimeout(tick, 1800); return; }
            } else {
                el.textContent = word.slice(0, --ci);
                if (ci === 0) { deleting = false; wi = (wi + 1) % words.length; }
            }
            setTimeout(tick, deleting ? 50 : 80);
        }
        setTimeout(tick, 1200);
    }

    /* ── Compteurs animés ── */
    function initCounters() {
        var els = document.querySelectorAll('.pm-stat-num[data-count]');
        if (!els.length) return;
        var observer = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
                if (!entry.isIntersecting) return;
                observer.unobserve(entry.target);
                var el = entry.target;
                var target = +el.dataset.count;
                var suffix = el.dataset.suffix || '';
                var duration = 1600;
                var start = performance.now();
                function animate(now) {
                    var progress = Math.min((now - start) / duration, 1);
                    var ease = 1 - Math.pow(1 - progress, 3);
                    var val = Math.round(ease * target);
                    el.textContent = val.toLocaleString('fr-FR') + suffix;
                    if (progress < 1) requestAnimationFrame(animate);
                }
                requestAnimationFrame(animate);
            });
        }, { threshold: 0.3 });
        els.forEach(function(el) { observer.observe(el); });
    }

    /* ── Carrousel avis ── */
    function initAvis() {
        var track = document.getElementById('pm-avis-track');
        if (!track || track.dataset.init) return;
        track.dataset.init = '1';
        var originals = [].slice.call(track.children);
        originals.forEach(function(n) { track.appendChild(n.cloneNode(true)); });
        var paused = false;
        track.addEventListener('mouseenter', function() { paused = true; });
        track.addEventListener('mouseleave', function() { paused = false; });
        var pos = 0;
        (function step() {
            if (!paused) {
                pos += 0.65;
                var half = track.scrollWidth / 2;
                if (half > 0 && pos >= half) pos -= half;
                track.scrollLeft = pos;
            }
            requestAnimationFrame(step);
        })();
    }

    /* ── Init ── */
    function init() {
        initParticles();
        initHero();
        initTypewriter();
        initCounters();
        initAvis();
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else { init(); }
})();
